import os
import re
import time
import json
import requests
from requests import get
from bs4 import BeautifulSoup
from urllib.request import urlopen as uReq
from urllib.request import Request
from datetime import datetime

def find_between(s, first, last):
    try:
        start = s.index(first) + len(first)
        end = s.index(last, start)
        return s[start:end]
    except ValueError:
        return ""


def get_all_pages():
    pages = []
    for i in range(1, 100):
        link = 'https://www.genshinimpact.wiki/w/Special:AllPages?from=&to=&namespace=0&limit=500&offset=' + str(i*500)
        r = get(link)
        soup = BeautifulSoup(r.text, 'html.parser')
        for tag in soup.find_all('a'):
            if 'href' in tag.attrs:
                pages.append(tag.attrs['href'])
    return pages


def get_all_data():
    all_pages = get_all_pages()
    data = []
    for page in all_pages:
        if page!= '/wiki/Category:Characters' and page!= '/wiki/Category:Weapons' and page!= '/wiki/Category:Artifacts':
            r = get('https://www.genshinimpact.wiki' + page)
            soup = BeautifulSoup(r.text, 'html.parser')
            for tag in soup.find_all('span', {'class':'mw-headline'}):
                data.append(tag.text)
    return data


def write_to_file(data):
    with open('genshin.txt', 'w', encoding='utf-8') as f:
        f.write(json.dumps(data))


def main():
    start_time = datetime.now()
    data = get_all_data()
    write_to_file(data)
    print('time: ', datetime.now() - start_time)


if __name__ == '__main__':
    main()

