#include <iostream>
using namespace std;

int fib(int n){
    if(n<=1)
        return n;
    int prev1 = 0;
    int prev2 = 1;
    int result = 0;
    for(int i=2;i<=n;i++){
        result = prev1+prev2;
        prev1 = prev2;
        prev2 = result;
    }
    return result;
}

int main(){
    int n;
    cin>>n;
    cout<<fib(n)<<endl;
    return 0;
}

class QueueUsingTwoStacks:
    def __init__(self):
        self.instack = []
        self.outstack = []

    def enqueue(self, item):
        self.instack.append(item)

    def dequeue(self):
        if not self.outstack:
            while self.instack:
                self.outstack.append(self.instack.pop())
        return self.outstack.pop()

# C++ Implementation
```c++
#include <bits/stdc++.h>
using namespace std;

int main()
{
    int a[5] = {1, 2, 3, 4, 5};
    int b[5] = {4, 5, 6, 7, 8};
    int m = 5;
    int n = 5;
    int i = 0, j = 0;
    while (i < m && j < n)
    {
        if (a[i] == b[j])
        {
            cout << a[i] << " ";
            i++;
            j++;
        }
        else if (a[i] < b[j])
            i++;
        else
            j++;
    }
    return 0;
}
```
In this implementation, we first define two arrays `a` and `b` with five elements each. We then define two variables `m` and `n` to store the lengths of the two arrays. We initialize two pointers `i` and `j` to 0. We then use a while loop to iterate through both arrays simultaneously. In each iteration, we check if the current elements of both arrays are equal. If they are, we print the common element and increment both pointers `i` and `j`. If the current element of array `a` is less than the current element of array `b`, we increment pointer `i`. Similarly, if the current element of array `b` is less than the current element of array `a`, we increment pointer `j`. This process continues until either `i` becomes equal to `m` or `j` becomes equal to `n`.
